const palettes={olive:{name:'CHLOROPHYLL / PALETTE 01',surface:'#D3D8AF',ink:'#222A20',signal:'#798743'},blue:{name:'VOLTAGE / PALETTE 02',surface:'#C8DCEC',ink:'#192F42',signal:'#496D91'},rose:{name:'AFTERGLOW / PALETTE 03',surface:'#E4C8BC',ink:'#3C292F',signal:'#935C67'}};
const site=document.querySelector('.atmos-site'),buttons=[...document.querySelectorAll('[data-palette]')];
for(const button of buttons)button.addEventListener('click',()=>{const palette=palettes[button.dataset.palette];if(!palette||!site)return;for(const key of['surface','ink','signal']){site.style.setProperty('--palette-'+key,palette[key]);document.querySelector('[data-color-value="'+key+'"]').textContent=palette[key]}for(const b of buttons)b.setAttribute('aria-pressed',String(b===button));document.querySelector('#atmos-palette-status').textContent=palette.name});
